// Asset metadata structures (tables are generated by tools/convert.py)
#pragma once
#include <nds.h>

typedef struct { u8 fmt, wlog, hlog, pad; u32 off; u32 size; } TexDef;
typedef struct { u8 tex, pad; u16 u, v, w, h; s16 dx, dy; } PartDef;
typedef struct { u16 first, count; } FrameDef;
typedef struct {
	const char *file;
	float scale;            // texels per drawn unit
	u16 nTex, nFrames, palCount, palOff;
	const TexDef *tex;
	const FrameDef *frames;
	const PartDef *parts;
} SheetDef;

typedef struct { u8 x, y, w, h; s8 ox, oy; u8 adv; } Glyph;
typedef struct {
	const char *file;
	u8 wlog, hlog;
	u8 lineh, ascent;
	const Glyph *glyphs;    // chars 32..126
} FontDef;

// ---------------------------------------------------------------------------
// stages (data/stages/*.json)
// ---------------------------------------------------------------------------
typedef struct {
	const char *name;
	const u8 *seq;          // sheet frames
	u8 n, loop;
	float fps;
	float offx, offy;       // world offset (-animOffsets * scale)
} PropAnim;

enum { PROP_STATIC, PROP_ANIM, PROP_SOLID };
typedef struct {
	const char *name;
	const SheetDef *sheet;
	u8 kind;
	float x, y, sfx, sfy;
	float w, h;             // solid color size
	u16 color;              // RGB15 tint (solid color for PROP_SOLID)
	float alpha;
	s16 z;
	float danceEvery;
	u8 nAnims;
	const PropAnim *anims;
	u8 startAnim;
	u8 pixel;
} PropDef;

typedef struct { float x, y, camx, camy; s16 z; float scale, sfx, sfy; } StageChar;
typedef struct {
	const char *id;
	float zoom;
	StageChar chars[3];     // bf, gf, dad
	u8 nProps;
	const PropDef *props;
} StageDef;

// ---------------------------------------------------------------------------
// songs / weeks
// ---------------------------------------------------------------------------
typedef struct {
	const char *id, *name, *artist;
	const StageDef *stage;
	u8 pixel;
	const char *player, *gf, *opp;   // character file tags
	const char *iconP, *iconO;
	u8 diffMask;
	u8 week;
} SongInfo;

typedef struct {
	const char *id, *name;
	u8 nSongs;
	u8 songs[4];
	u32 bg;
} WeekInfo;

typedef struct { const char *tag, *icon; u8 hasDead; } ChrInfo;
typedef struct { const char *name; const SheetDef *sheet; } IconDef;

typedef struct {
	const SheetDef *sheet;
	const u8 *seqA; int lenA;
	const u8 *seqB; int lenB;
	u8 dance;
	float offx, offy;
} WeekProp;
typedef struct { WeekProp p[3]; u8 n; } WeekProps;

// ---------------------------------------------------------------------------
// note styles
// ---------------------------------------------------------------------------
typedef struct {
	const SheetDef *sheet;
	u8 fStatic[4], fNote[4], fHold[4], fEnd[4];
	u8 press[4][8];
	u8 nPress[4];
	u8 confirm[4][8];
	u8 nConfirm[4];
	float holdW;            // hold trail width (hud units)
	float endH;             // hold end cap height (hud units)
	u8 pixel;
} NoteSkin;

typedef struct {
	const SheetDef *sheet;
	u16 seq[4][2][2];       // [dir][variant] = {first frame, count}
	float alpha;
} SplashDef;

// ---------------------------------------------------------------------------
// runtime files
// ---------------------------------------------------------------------------
// .chr (tools/convert.py write_chr)
typedef struct {
	char magic[4];
	float ts;               // texels per world unit
	u8 slotW, slotH, pixel, flip;
	float W, H;             // hitbox (world)
	float gx, gy;           // globalOffsets
	float camx, camy;       // cameraOffsets
	float singTime, danceEvery;
	u16 nFrames, nAnims;
	u32 offAnims, offSeq, offFrames, offPal, offPix;
} ChrHeader;

typedef struct {
	char name[24];
	float fps;
	u8 loop, pad;
	u16 n, start, pad2;
	float offx, offy;
} ChrAnimRec;

typedef struct {
	u32 off, csize;
	u16 w4, h, cw, pad;
	float dx, dy, ww, wh;
} ChrFrameRec;

// .cht (tools/convert.py convert_chart)
typedef struct { char magic[4]; float speed; u16 nTime, nEvents; u32 nNotes[2]; } ChartHeader;
typedef struct { float t, bpm; } TimeChange;
typedef struct { float t; u8 type; s8 i0; u8 ease, pad; float f[4]; char s[16]; } ChartEvent;
typedef struct { float t, len; u8 dir, kind; u16 pad; } ChartNote;
enum { CEV_FOCUS, CEV_ZOOM, CEV_BOP, CEV_ANIM, CEV_SCROLL };
enum { KIND_NORMAL, KIND_NOANIM, KIND_ALT, KIND_UGH, KIND_HEH };
